def max_sum(arr):
    n = len(arr)
    inc = arr[:]  # max sum of increasing subsequence ending at i
    dec = arr[:]  # max sum of decreasing subsequence starting at i

    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    for i in range(n-1, -1, -1):
        for j in range(n-1, i, -1):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    max_sum_bitonic = 0
    for i in range(n):
        # Subtract arr[i] because it is counted twice in inc[i] + dec[i]
        max_sum_bitonic = max(max_sum_bitonic, inc[i] + dec[i] - arr[i])

    return max_sum_bitonic
```

